void drawGitHub(int left,int top,int size,uint16_t color=TFT_WHITE) {
  if(size<1 || size>468)return;
  const int height=max(1,(size*96+49)/98);
  for(int y=0;y<height;y++) {
    int sy=(2*y+1)*96/(2*height),start=-1;
    for(int x=0;x<=size;x++) {
      bool ink=false;
      if(x<size) {
        int sx=(2*x+1)*98/(2*size);
        ink=(pgm_read_byte(GITHUB_MARK_BITS+sy*13+sx/8)&(0x80>>(sx%8)))!=0;
      }
      if(ink && start<0)start=x;
      if(!ink && start>=0) {M5.Display.drawFastHLine(left+start,top+y,x-start,color);start=-1;}
    }
  }
}
